'use client';

import { FC, MouseEvent, useCallback } from 'react';
import { IconInfoCircle } from '@tabler/icons-react';
import { IconButton } from '@epam/ai-dial-ui-kit';

import { useAppContext } from '@/src/context/AppContext';
import Hint from '@/src/components/Common/Sidebar/Hint';

interface Props {
  hintTitle: string;
  hintText: string;
  displayName: string;
}

const HeaderWithHintButton: FC<Props> = ({ displayName, hintText, hintTitle }) => {
  const { showSidebar, closeSidebar } = useAppContext().sidebar;

  const onClick = useCallback(
    (e: MouseEvent<HTMLButtonElement>) => {
      e.stopPropagation();
      showSidebar(<Hint title={hintTitle} text={hintText} onClose={closeSidebar} />);
    },
    [hintText, hintTitle, showSidebar, closeSidebar],
  );

  return (
    <div className="flex items-center w-full justify-end gap-x-3">
      <IconButton className="p-0 size-auto" icon={<IconInfoCircle size={14} />} onClick={onClick} />
      {displayName}
    </div>
  );
};

export default HeaderWithHintButton;
